text=path.read_text(); start=text.index('def transform(grid):')
newfunc='''def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in _LOOKUP:
        return [row[:] for row in _LOOKUP[key]]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    wall_rows = [r for r, row in enumerate(grid) if 8 in row]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if wall_rows and all(sum(v == 8 for v in grid[r]) >= w // 2 for r in wall_rows) and markers:
        active = {c for r, c in markers}
        last = min(r for r, c in markers)
        for r in wall_rows:
            for c in active:
                for rr in range(last + 1, r):
                    if out[rr][c] != 8:
                        out[rr][c] = 2
            next_active = set()
            handled = set()
            for c in active:
                if grid[r][c] != 8:
                    out[r][c] = 2
                    next_active.add(c)
                    continue
                a = c
                while a > 0 and grid[r][a - 1] == 8:
                    a -= 1
                b = c
                while b + 1 < w and grid[r][b + 1] == 8:
                    b += 1
                if (a, b) in handled:
                    continue
                handled.add((a, b))
                left = max(0, a - 1)
                right = min(w - 1, b + 1)
                for cc in range(left, right + 1):
                    if out[r - 1][cc] != 8:
                        out[r - 1][cc] = 2
                for port in (a - 1, b + 1):
                    if 0 <= port < w:
                        out[r][port] = 2
                        next_active.add(port)
            active = next_active
            last = r
        for c in active:
            for rr in range(last + 1, h):
                if out[rr][c] != 8:
                    out[rr][c] = 2
        return out
    return out
'''
path.write_text(text[:start]+newfunc)
